<?php
declare(strict_types=1);
const VAULT_ITERATIONS=600000;
const VAULT_SESSION_MS=900000;
function vaultBytes(mixed $value,int $min,?int $max=null): string {
    $max=$max??$min;if(!is_string($value)||strlen($value)>(int)ceil($max/3)*4)throw new RuntimeException('Invalid encrypted data');$bytes=base64_decode($value,true);if($bytes===false||strlen($bytes)<$min||strlen($bytes)>$max||base64_encode($bytes)!==$value)throw new RuntimeException('Invalid encrypted data');return $bytes;
}
function vaultSeal(string $value,string $key,string $aad): array {$iv=random_bytes(12);$tag='';$encrypted=openssl_encrypt($value,'aes-256-gcm',$key,OPENSSL_RAW_DATA,$iv,$tag,$aad,16);if($encrypted===false)throw new RuntimeException('Encryption failed');return ['version'=>1,'iv'=>base64_encode($iv),'tag'=>base64_encode($tag),'data'=>base64_encode($encrypted)];}
function vaultOpen(array $e,string $key,string $aad): string {if(($e['version']??null)!==1)throw new RuntimeException('Invalid encrypted data');$result=openssl_decrypt(vaultBytes($e['data']??null,1,32768),'aes-256-gcm',$key,OPENSSL_RAW_DATA,vaultBytes($e['iv']??null,12),vaultBytes($e['tag']??null,16),$aad);if($result===false)throw new RuntimeException('Invalid encrypted data');return $result;}
function vaultPassword(mixed $value,string $common=''): string {if(!is_string($value)||!preg_match('//u',$value)||strlen($value)>512||preg_match_all('/./us',$value)<7||preg_match_all('/./us',$value)>128)fail('Mật khẩu kho cần từ 7 đến 128 ký tự.');if($common!==''&&hash_equals($common,$value))fail('Chọn mật khẩu kho khác mật khẩu truy cập website.');return $value;}
function vaultWrap(string $password,string $master): array {$salt=random_bytes(16);$key=hash_pbkdf2('sha256',$password,$salt,VAULT_ITERATIONS,32,true);return ['version'=>1,'kdf'=>'pbkdf2-sha256','iterations'=>VAULT_ITERATIONS,'salt'=>base64_encode($salt),'wrapped_key'=>vaultSeal(base64_encode($master),$key,'family-vault-key-v1')];}
function vaultValidConfig(array $c): void {if(($c['version']??null)!==1||($c['kdf']??null)!=='pbkdf2-sha256'||($c['iterations']??null)!==VAULT_ITERATIONS)throw new RuntimeException('Invalid vault configuration');vaultBytes($c['salt']??null,16);$e=$c['wrapped_key']??[];if(($e['version']??null)!==1)throw new RuntimeException('Invalid vault configuration');vaultBytes($e['iv']??null,12);vaultBytes($e['tag']??null,16);vaultBytes($e['data']??null,1,32768);}
