function vaultBase32(string $value): string {$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits=0;$acc=0;$out='';foreach(str_split($value)as $letter){$n=strpos($alphabet,$letter);if($n===false)fail('Khóa 2FA Base32 chỉ dùng A–Z và 2–7; kiểm tra lại khóa từ nơi cấp.');$acc=($acc<<5)|$n;$bits+=5;if($bits>=8){$bits-=8;$out.=chr(($acc>>$bits)&255);$acc&=(1<<$bits)-1;}}if($acc!==0||!in_array($bits,[0,1,2,3,4],true)||strlen($out)<10||strlen($out)>160)fail('Khóa 2FA không hợp lệ. Nhập khóa bí mật, không phải mã 6 số hoặc mã dự phòng.');return $out;}
function vaultTotpConfig(mixed $value): array {
    if(!is_string($value)||strlen($value)>2048)fail('Khóa 2FA không hợp lệ.');$secret=$value;$algorithm='SHA1';$period=30;
    if(str_starts_with(trim($value),'otpauth:')){$url=parse_url(trim($value));if(!$url||($url['scheme']??'')!=='otpauth'||($url['host']??'')!=='totp')fail('Chỉ hỗ trợ khóa TOTP tạo mã theo thời gian.');parse_str($url['query']??'',$params);foreach(['secret','algorithm','period','digits']as $field)if(isset($params[$field])&&!is_string($params[$field]))fail('Thiết lập khóa 2FA không được hỗ trợ.');$secret=$params['secret']??'';$algorithm=strtoupper($params['algorithm']??'SHA1');$period=$params['period']??'30';if(($params['digits']??'6')!=='6')fail('Kho hiện hỗ trợ mã 2FA 6 số.');if(!is_string($secret)||!is_string($period)||!preg_match('/^\d+$/D',$period))fail('Thiết lập khóa 2FA không được hỗ trợ.');$period=(int)$period;}
    $secret=strtoupper(preg_replace('/[\s-]/','',trim($secret)));$secret=rtrim($secret,'=');if($secret==='')return ['secret'=>'','algorithm'=>'SHA1','period'=>30];
    if(!preg_match('/^[A-Z2-7]{16,256}$/D',$secret))fail('Khóa 2FA Base32 chỉ dùng A–Z và 2–7; kiểm tra lại khóa từ nơi cấp.');vaultBase32($secret);if(!in_array($algorithm,['SHA1','SHA256','SHA512'],true)||$period<15||$period>120)fail('Thiết lập khóa 2FA không được hỗ trợ.');return ['secret'=>$secret,'algorithm'=>$algorithm,'period'=>$period];
}
function vaultTotp(array $c,?int $now=null): array {if(!$c['secret'])return ['code'=>'','expires_at'=>null,'period'=>30];$now=$now??(int)floor(microtime(true)*1000);$counter=(int)floor($now/1000/$c['period']);$bytes=pack('N2',(int)floor($counter/4294967296),$counter%4294967296);$digest=hash_hmac(strtolower($c['algorithm']),$bytes,vaultBase32($c['secret']),true);$offset=ord($digest[strlen($digest)-1])&15;$binary=unpack('N',substr($digest,$offset,4))[1]&0x7fffffff;return ['code'=>str_pad((string)($binary%1000000),6,'0',STR_PAD_LEFT),'expires_at'=>($counter+1)*$c['period']*1000,'period'=>$c['period']];}
function vaultTotpText(array $c,string $email): string {return !$c['secret']?'':($c['algorithm']==='SHA1'&&$c['period']===30?$c['secret']:'otpauth://totp/'.rawurlencode($email).'?secret='.$c['secret'].'&algorithm='.$c['algorithm'].'&digits=6&period='.$c['period']);}
function vaultValidateBackup(array $meta,array $items): void {
    if(count($meta)>1)throw new RuntimeException('Invalid encrypted vault backup');if(!$meta){if($items)throw new RuntimeException('Missing vault configuration');return;}
    if(($meta[0]['name']??'')!=='config'||!is_string($meta[0]['value']??null))throw new RuntimeException('Invalid vault configuration');vaultValidConfig(json_decode($meta[0]['value'],true,512,JSON_THROW_ON_ERROR));$ids=[];
    foreach($items as $r){if(!is_int($r['id']??null)||$r['id']<1||isset($ids[$r['id']])||!is_int($r['revision']??null)||$r['revision']<0||!is_string($r['payload']??null)||strlen($r['payload'])>50000||!is_string($r['created_at']??null)||strtotime($r['created_at'])===false||!is_string($r['updated_at']??null)||strtotime($r['updated_at'])===false)throw new RuntimeException('Invalid encrypted vault entry');$ids[$r['id']]=true;$e=json_decode($r['payload'],true,512,JSON_THROW_ON_ERROR);if(($e['version']??null)!==1)throw new RuntimeException('Invalid encrypted vault entry');vaultBytes($e['iv']??null,12);vaultBytes($e['tag']??null,16);vaultBytes($e['data']??null,1,32768);}
}
function vaultMeta(PDO $db): string {return one($db,"SELECT value FROM vault_meta WHERE name='config'")['value']??'';}
function vaultToken(): string {$raw=$_COOKIE['fam_vault']??'';return is_string($raw)&&strlen($raw)<5000?$raw:'';}
function vaultSessionKey(array $c): string {return hash('sha256',"family-vault-session\0".$c['db_password']."\0".$c['access_password']."\0".$c['public_origin'],true);}
function vaultCookie(array $c,string $value,bool $close=false): void {setcookie('fam_vault',$value,['expires'=>$close?1:time()+900,'path'=>'/api/vault','secure'=>$c['secure'],'httponly'=>true,'samesite'=>'Strict']);}
function vaultAuthorize(PDO $db,array $c): array|false {
    $raw=vaultToken();$meta=vaultMeta($db);if(!$raw||!$meta)return false;$row=one($db,'SELECT expires_at FROM vault_sessions WHERE token_hash=?',[hash('sha256',$raw)]);if(!$row||$row['expires_at']<=microtime(true)*1000)return false;
    try{$e=json_decode(base64_decode(strtr($raw,'-_','+/'),true),true,512,JSON_THROW_ON_ERROR);$info=json_decode(vaultOpen($e,vaultSessionKey($c),'family-vault-session-v1'),true,512,JSON_THROW_ON_ERROR);$key=vaultBytes($info['key']??null,32);if(($info['config_hash']??'')!==hash('sha256',$meta)||($info['expires']??null)!==$row['expires_at'])return false;return ['key'=>$key,'expires'=>$info['expires']];}catch(Throwable $e){return false;}
}
function vaultIssueSession(PDO $db,array $c,string $key): array {$expires=(int)floor(microtime(true)*1000)+VAULT_SESSION_MS;$data=json_encode(['key'=>base64_encode($key),'expires'=>$expires,'config_hash'=>hash('sha256',vaultMeta($db))],JSON_THROW_ON_ERROR);$raw=rtrim(strtr(base64_encode(json_encode(vaultSeal($data,vaultSessionKey($c),'family-vault-session-v1'),JSON_THROW_ON_ERROR)),'+/','-_'),'=');q($db,'DELETE FROM vault_sessions WHERE token_hash=? OR expires_at<=?',[hash('sha256',vaultToken()),(int)floor(microtime(true)*1000)]);q($db,'INSERT INTO vault_sessions(token_hash,expires_at) VALUES (?,?)',[hash('sha256',$raw),$expires]);vaultCookie($c,$raw);return ['ok'=>true,'session_expires'=>$expires];}
function vaultPasswordKey(PDO $db,mixed $password): string {
    $record=one($db,"SELECT value FROM app_meta WHERE name='vault_attempts'");$a=$record?json_decode($record['value'],true):['end'=>0,'count'=>0];if(time()>$a['end'])$a=['end'=>time()+600,'count'=>0];if($a['count']>=10)fail('Đã thử nhiều lần. Chờ 10 phút rồi mở kho lại.',429);
    try{if(!is_string($password)||strlen($password)>512)throw new RuntimeException('Invalid password');$key=vaultUnwrap($password,json_decode(vaultMeta($db),true,512,JSON_THROW_ON_ERROR));q($db,"DELETE FROM app_meta WHERE name='vault_attempts'");return $key;}catch(Throwable $e){$a['count']++;q($db,"INSERT INTO app_meta(name,value) VALUES ('vault_attempts',?) ON DUPLICATE KEY UPDATE value=VALUES(value)",[json_encode($a)]);fail('Mật khẩu kho không đúng.',403);}
}
function vaultRead(array $row,string $key): array {try{return json_decode(vaultOpen(json_decode($row['payload'],true,512,JSON_THROW_ON_ERROR),$key,'family-vault-item-v1:'.$row['id']),true,512,JSON_THROW_ON_ERROR);}catch(Throwable $e){fail('Không thể giải mã hồ sơ kho. Kiểm tra file sao lưu hoặc mở lại kho.',500);}}
function vaultGuard(array|false $row,array $d): void {if(!$row)fail('Không tìm thấy hồ sơ trong kho.',404);if(!is_int($d['revision']??null)||$d['revision']!==$row['revision']||($d['expected_created_at']??null)!==$row['created_at'])fail('Hồ sơ kho đã thay đổi. Tải lại kho rồi thử lại.',409);}
function vaultMutation(PDO $db,string $action,callable $operation): mixed {beginAudit($db,$action);try{one($db,"SELECT value FROM vault_meta WHERE name='config' FOR UPDATE");$result=$operation();finishAudit();return $result;}catch(Throwable $e){finishAudit(false);throw $e;}}
function vaultFields(array $d): array {
    if(!is_string($d['password']??null)||strlen($d['password'])>8192||!preg_match('//u',$d['password'])||preg_match_all('/./us',$d['password'])>2048)fail('Mật khẩu tài khoản không hợp lệ.');
    return ['email'=>email($d['email']??''),'label'=>text($d['label']??'',200),'note'=>text($d['note']??'',1000),'password'=>$d['password'],'totp'=>vaultTotpConfig($d['totp']??''),'recovery_email'=>!empty($d['recovery_email'])?email($d['recovery_email']):''];
}
function vaultImportItems(PDO $db,array $d,string $key): array {
    if(!is_array($d['items']??null)||!array_is_list($d['items'])||count($d['items'])<1||count($d['items'])>500)fail('Chọn từ 1 đến 500 tài khoản để nhập.');$seen=[];$items=[];
    foreach(all($db,'SELECT * FROM vault_items'.($db->inTransaction()?' FOR UPDATE':'')) as $row)$seen[vaultRead($row,$key)['email']]=true;
    foreach($d['items'] as $index=>$row){$line=is_array($row)&&is_int($row['line']??null)&&$row['line']>0?$row['line']:$index+2;try{if(!is_array($row))fail('Thông tin không hợp lệ.');$item=vaultFields($row);}catch(Throwable $e){fail("Dòng $line: ".$e->getMessage());}if(isset($seen[$item['email']]))fail("Dòng $line: tài khoản đã có trong kho hoặc trùng trong bảng nhập.",409);$seen[$item['email']]=true;$items[]=['line'=>$line,...$item];}
    return $items;
}
function vaultInsert(PDO $db,array $item,string $key): int {$now=stamp();q($db,'INSERT INTO vault_items(payload,revision,created_at,updated_at) VALUES (?,0,?,?)',['',$now,$now]);$id=(int)$db->lastInsertId();q($db,'UPDATE vault_items SET payload=? WHERE id=?',[json_encode(vaultSeal(json_encode($item,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$key,'family-vault-item-v1:'.$id),JSON_THROW_ON_ERROR),$id]);return $id;}
function vaultRequest(PDO $db,array $c,string $route,string $method): never {
    if(!function_exists('openssl_encrypt')||!in_array('aes-256-gcm',openssl_get_cipher_methods(),true))fail('Kho cần extension OpenSSL. Bật OpenSSL trong PHP Configuration của website.',503);
    $meta=vaultMeta($db);
    if($method==='GET'&&$route==='/api/vault/status'){$auth=vaultAuthorize($db,$c);reply(['configured'=>$meta!=='','unlocked'=>(bool)$auth,'session_expires'=>$auth['expires']??null]);}
    $d=in_array($method,['POST','PATCH','DELETE'],true)?body(str_starts_with($route,'/api/vault/import')?2000000:32768):[];
    if($method==='POST'&&$route==='/api/vault/setup'){
        if($meta||one($db,'SELECT id FROM vault_items LIMIT 1'))fail('Kho đã có mật khẩu. Chọn Mở kho.',409);$password=vaultPassword($d['password']??null,$c['access_password']);if(($d['confirm_password']??null)!==$password)fail('Hai mật khẩu kho chưa giống nhau.');$key=random_bytes(32);
        reply(vaultMutation($db,'Tạo mật khẩu kho',function()use($db,$c,$password,$key){q($db,"INSERT INTO vault_meta(name,value) VALUES ('config',?)",[json_encode(vaultWrap($password,$key),JSON_THROW_ON_ERROR)]);logEntry($db,'Cá nhân: tạo kho tài khoản đã mã hóa');return vaultIssueSession($db,$c,$key);}));
    }
    if($method==='POST'&&$route==='/api/vault/unlock'){if(!$meta)fail('Tạo mật khẩu kho lần đầu.');reply(vaultIssueSession($db,$c,vaultPasswordKey($db,$d['password']??null)));}
    if($method==='POST'&&$route==='/api/vault/lock'){q($db,'DELETE FROM vault_sessions WHERE token_hash=?',[hash('sha256',vaultToken())]);vaultCookie($c,'',true);reply(['ok'=>true]);}
    $auth=vaultAuthorize($db,$c);if(!$auth)fail('Kho đã khóa. Nhập mật khẩu kho để mở lại.',423);$key=$auth['key'];
    if($method==='POST'&&$route==='/api/vault/import/preview'){$rows=vaultImportItems($db,$d,$key);reply(['count'=>count($rows),'items'=>array_map(fn($i)=>['line'=>$i['line'],'email'=>$i['email'],'label'=>$i['label'],'note'=>$i['note'],'recovery_email'=>$i['recovery_email'],'has_password'=>$i['password']!=='','has_totp'=>$i['totp']['secret']!==''],$rows)]);}
    if($method==='POST'&&$route==='/api/vault/import')reply(vaultMutation($db,'Nhập hàng loạt kho tài khoản',function()use($db,$d,$key){$rows=vaultImportItems($db,$d,$key);$ids=[];foreach($rows as $item){unset($item['line']);$ids[]=vaultInsert($db,$item,$key);}logEntry($db,'Cá nhân: nhập '.count($ids).' hồ sơ kho đã mã hóa');return ['ok'=>true,'count'=>count($ids),'ids'=>$ids];}));
    if($method==='GET'&&$route==='/api/vault/items'){$now=(int)floor(microtime(true)*1000);$items=array_map(function($row)use($key,$now){$item=vaultRead($row,$key);return ['id'=>$row['id'],'revision'=>$row['revision'],'created_at'=>$row['created_at'],'updated_at'=>$row['updated_at'],'email'=>$item['email'],'label'=>$item['label'],'note'=>$item['note']??'','recovery_email'=>$item['recovery_email'],'has_password'=>$item['password']!=='','has_totp'=>$item['totp']['secret']!=='','totp_key'=>vaultTotpText($item['totp'],$item['email']),...vaultTotp($item['totp'],$now)];},all($db,'SELECT * FROM vault_items ORDER BY id DESC'));reply(['items'=>$items,'server_time'=>$now,'session_expires'=>$auth['expires']]);}
    if($method==='POST'&&$route==='/api/vault/password'){$old=vaultPasswordKey($db,$d['current_password']??null);if(!hash_equals($key,$old))fail('Mật khẩu kho không đúng.',403);$password=vaultPassword($d['password']??null,$c['access_password']);if(($d['confirm_password']??null)!==$password)fail('Hai mật khẩu kho chưa giống nhau.');reply(vaultMutation($db,'Đổi mật khẩu kho',function()use($db,$c,$key,$password){q($db,"UPDATE vault_meta SET value=? WHERE name='config'",[json_encode(vaultWrap($password,$key),JSON_THROW_ON_ERROR)]);q($db,'DELETE FROM vault_sessions');logEntry($db,'Cá nhân: đổi mật khẩu kho, khóa các phiên cũ');return vaultIssueSession($db,$c,$key);}));}
    $match=[];$id=preg_match('~^/api/vault/items/(\d+)$~D',$route,$match)?(int)$match[1]:null;
    if($method==='GET'&&$id){$row=one($db,'SELECT * FROM vault_items WHERE id=?',[$id]);if(!$row)fail('Không tìm thấy hồ sơ trong kho.',404);$item=vaultRead($row,$key);reply([...$item,'note'=>$item['note']??'','totp'=>vaultTotpText($item['totp'],$item['email']),'id'=>$id,'revision'=>$row['revision'],'created_at'=>$row['created_at']]);}
    if(($method==='POST'&&$route==='/api/vault/items')||($method==='PATCH'&&$id)){
        $item=vaultFields($d);
        reply(vaultMutation($db,$id?'Sửa hồ sơ kho':'Thêm hồ sơ kho',function()use($db,$key,$item,$id,$d){if($id)vaultGuard(one($db,'SELECT * FROM vault_items WHERE id=? FOR UPDATE',[$id]),$d);foreach(all($db,'SELECT * FROM vault_items WHERE id!=? FOR UPDATE',[$id??0]) as $other)if(vaultRead($other,$key)['email']===$item['email'])fail('Tài khoản này đã có trong kho.',409);$now=stamp();$next=$id;if(!$next){q($db,'INSERT INTO vault_items(payload,revision,created_at,updated_at) VALUES (?,0,?,?)',['',$now,$now]);$next=(int)$db->lastInsertId();}q($db,'UPDATE vault_items SET payload=?,updated_at=?,revision=revision+? WHERE id=?',[json_encode(vaultSeal(json_encode($item,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR),$key,'family-vault-item-v1:'.$next),JSON_THROW_ON_ERROR),$now,$id?1:0,$next]);logEntry($db,"Cá nhân: ".($id?'sửa':'thêm')." hồ sơ kho #$next");return ['ok'=>true,'id'=>$next];}));
    }
